var maximumScore = function(a, b, c) {
    const piles = [a, b, c];
    let score = 0;
    while (true) {
        piles.sort((x, y) => y - x);
        if (piles[1] === 0) break;
        piles[0]--;
        piles[1]--;
        score++;
    }
    return score;
};

